-- The Cartographer of Ash (32 chapters)
insert into public.stories (id, author_id, title, slug, synopsis, status, rating, created_at)
values ('38bf5630-62ec-54d4-af2b-f9b4c804b5f3', '555aeb0c-a518-528a-ae47-6ae57437c77d', 'The Cartographer of Ash', 'the-cartographer-of-ash', 'In Cindermere, whatever is drawn in ash-ink becomes true: streets bend, rivers move, doors appear. Apprentice cartographer Ilse Varn inherits her murdered master''s last, unfinished map, and with it a district the Guild swears does not exist. To finish the map is to make that district real. To leave it blank is to let someone erase it, and everyone inside.', 'ongoing', 'everyone', now() - interval '74.84 days')
on conflict (id) do nothing;
insert into public.story_genres (story_id, genre_id) select '38bf5630-62ec-54d4-af2b-f9b4c804b5f3', id from public.genres where slug in ('fantasy') on conflict do nothing;
insert into public.tags (slug, name) values ('magic-system', 'Magic System'), ('found-family', 'Found Family'), ('slow-burn', 'Slow Burn') on conflict (slug) do nothing;
insert into public.story_tags (story_id, tag_id) select '38bf5630-62ec-54d4-af2b-f9b4c804b5f3', id from public.tags where slug in ('magic-system', 'found-family', 'slow-burn') on conflict do nothing;
insert into public.chapters (id, story_id, number, title, body, status, published_at, created_at) values
  ('42de8de1-f137-5355-acf2-3dcf85f5e43c', '38bf5630-62ec-54d4-af2b-f9b4c804b5f3', 1, 'The Unfinished Map', 'The first rule of ash-ink is that it does not forgive. Master Oren used to say it while scraping a wrong line off vellum with a bone knife, and the street outside would groan as it unbent.

Ilse Varn had been his apprentice for six years, long enough to know the sound a city makes when a map changes its mind. Tonight there was no sound at all. That was how she knew something had gone wrong before she found him at the drafting table, pen still in his hand, the lamp burned down to a coin of blue flame.

On the table lay a map of Cindermere she had never seen. Every street she knew was there, inked in his careful hand. And in the middle, where the Guild''s maps showed only a smudge of grey, someone had drawn the edge of a district and stopped.

Ash fell over Cindermere the way snow falls elsewhere, soft and constant, settling in the gutters and on the brims of hats.

Corvin said, "A map is a promise. Draw carefully, or the city will hold you to it."

Somewhere across the city, a street she had never drawn quietly folded itself away.', 'published', now() - interval '73.842 days', now() - interval '73.842 days'),
  ('c563213e-8b61-5947-a6f8-e0923e2aff0e', '38bf5630-62ec-54d4-af2b-f9b4c804b5f3', 2, 'Guild Inquest', 'In which Mother Agathe rules Oren''s death a heart failure and seizes his workshop. Ilse notices the inquest record lists his ink as ''already confiscated'' an hour before anyone could have known.

Below the bridges the canal ran black and slow, carrying the day''s scraped lines out toward the sea.

Every person she met had a version of Cindermere in their head. Ilse was beginning to suspect none of them matched.

Corvin said, "A map is a promise. Draw carefully, or the city will hold you to it."

The Guild bells rang the hour, and somewhere a street creaked as a surveyor''s correction took hold.

She had spent six years learning to draw what was there. Nobody had taught her what to do when the truth itself was missing.

The bells rang once more, though it was not yet the hour.', 'published', now() - interval '71.747 days', now() - interval '71.747 days'),
  ('c0724841-12fc-5f20-abea-4dd9ad035fd3', '38bf5630-62ec-54d4-af2b-f9b4c804b5f3', 3, 'The Exile at the Docks', 'In which following a name in Oren''s ledger, Ilse finds Corvin, a surveyor expelled from the Guild for mapping a street that was not approved. He refuses to help her.

Ash fell over Cindermere the way snow falls elsewhere, soft and constant, settling in the gutters and on the brims of hats.

There was a weight to the unfinished map in her satchel, heavier than vellum had any right to be.

Corvin said, "Every line you draw takes something from somewhere. Find out what before you lift the pen."

The Unmarked was quiet at this hour, its rooftops a jagged line against a sky the colour of old coins.

Every person she met had a version of Cindermere in their head. Ilse was beginning to suspect none of them matched.

The bells rang once more, though it was not yet the hour.', 'published', now() - interval '69.442 days', now() - interval '69.442 days'),
  ('5ad945bf-11e6-5bc1-a015-9644a1991f6b', '38bf5630-62ec-54d4-af2b-f9b4c804b5f3', 4, 'Ink and Bone', 'In which Ilse tests the unfinished map by drawing a single doorway. A door appears in an alley wall, opening onto a staircase that should not exist.

Below the bridges the canal ran black and slow, carrying the day''s scraped lines out toward the sea.

Ilse thought of Master Oren''s hands, steady even when the lamp guttered, and tried to make her own as still.

"Everyone says the Unmarked''s empty." Pell paused. "Funny how they lock the gates, then."

The Guild bells rang the hour, and somewhere a street creaked as a surveyor''s correction took hold.

There was a weight to the unfinished map in her satchel, heavier than vellum had any right to be.

Corvin said, "Every line you draw takes something from somewhere. Find out what before you lift the pen."

When she looked down at the map again, a line she had not inked was drying in the margin.', 'published', now() - interval '67.156 days', now() - interval '67.156 days'),
  ('c24907a1-1b66-5066-a8f8-cffe83e7cde1', '38bf5630-62ec-54d4-af2b-f9b4c804b5f3', 5, 'Pell', 'In which a street kid named Pell steals the satchel holding the map. Ilse chases her across three shifting bridges and wins it back by offering her a job instead.

Ash fell over Cindermere the way snow falls elsewhere, soft and constant, settling in the gutters and on the brims of hats.

For the first time, Ilse wondered whether the Guild had ever been drawing the city, or only drawing it smaller.

"If you''re going to change the city, change it so the bakery''s closer," Pell said.

The Unmarked was quiet at this hour, its rooftops a jagged line against a sky the colour of old coins.

Ilse thought of Master Oren''s hands, steady even when the lamp guttered, and tried to make her own as still.

"Everyone says the Unmarked''s empty." Pell paused. "Funny how they lock the gates, then."

The bells rang once more, though it was not yet the hour.', 'published', now() - interval '65.004 days', now() - interval '65.004 days'),
  ('af7cc05a-2d34-5077-aff2-75940745a2d8', '38bf5630-62ec-54d4-af2b-f9b4c804b5f3', 6, 'The Grey District', 'In which Ilse, Pell and a reluctant Corvin climb the wall into the Unmarked. It is not empty: hundreds of people live there, unrecorded and unprotected.

Below the bridges the canal ran black and slow, carrying the day''s scraped lines out toward the sea.

She had spent six years learning to draw what was there. Nobody had taught her what to do when the truth itself was missing.

"The Guild does not hide things, child." Mother Agathe paused. "It decides what is worth seeing."

The Guild bells rang the hour, and somewhere a street creaked as a surveyor''s correction took hold.

For the first time, Ilse wondered whether the Guild had ever been drawing the city, or only drawing it smaller.

The bells rang once more, though it was not yet the hour.', 'published', now() - interval '62.927 days', now() - interval '62.927 days'),
  ('c1787e61-182c-5b0c-a2ab-c33171ab2029', '38bf5630-62ec-54d4-af2b-f9b4c804b5f3', 7, 'People Without Streets', 'In which The Unmarked''s residents explain that their homes vanish whenever the Guild redraws the official maps. They call it ''the scraping''.

Ash fell over Cindermere the way snow falls elsewhere, soft and constant, settling in the gutters and on the brims of hats.

Every person she met had a version of Cindermere in their head. Ilse was beginning to suspect none of them matched.

Corvin said, "A map is a promise. Draw carefully, or the city will hold you to it."

The Unmarked was quiet at this hour, its rooftops a jagged line against a sky the colour of old coins.

She had spent six years learning to draw what was there. Nobody had taught her what to do when the truth itself was missing.

The bells rang once more, though it was not yet the hour.', 'published', now() - interval '60.647 days', now() - interval '60.647 days'),
  ('076489ce-fbfb-58cb-a789-86a0c8910283', '38bf5630-62ec-54d4-af2b-f9b4c804b5f3', 8, 'Corvin''s Price', 'In which Corvin agrees to teach Ilse true surveying in exchange for her copying one map he needs: the original survey that got him expelled.

Below the bridges the canal ran black and slow, carrying the day''s scraped lines out toward the sea.

There was a weight to the unfinished map in her satchel, heavier than vellum had any right to be.

Corvin said, "Every line you draw takes something from somewhere. Find out what before you lift the pen."

The Guild bells rang the hour, and somewhere a street creaked as a surveyor''s correction took hold.

Every person she met had a version of Cindermere in their head. Ilse was beginning to suspect none of them matched.

"A map is a promise." Corvin paused. "Draw carefully, or the city will hold you to it."

The bells rang once more, though it was not yet the hour.', 'published', now() - interval '58.306 days', now() - interval '58.306 days'),
  ('f7e495d0-5762-55b3-aa4e-b0e26f961aed', '38bf5630-62ec-54d4-af2b-f9b4c804b5f3', 9, 'Measuring the Dark', 'In which Ilse learns to survey by counting steps, bells and the slope of the canal. She maps her first true street in the Unmarked and it holds.

Ash fell over Cindermere the way snow falls elsewhere, soft and constant, settling in the gutters and on the brims of hats.

Ilse thought of Master Oren''s hands, steady even when the lamp guttered, and tried to make her own as still.

"Everyone says the Unmarked''s empty." Pell paused. "Funny how they lock the gates, then."

The Unmarked was quiet at this hour, its rooftops a jagged line against a sky the colour of old coins.

There was a weight to the unfinished map in her satchel, heavier than vellum had any right to be.

"Every line you draw takes something from somewhere. Find out what before you lift the pen," Corvin said.

By morning, the Guild had posted a notice on every door, and her name was on it.', 'published', now() - interval '56.204 days', now() - interval '56.204 days'),
  ('182f91bb-a8f5-57b7-aa76-09b09f3778c9', '38bf5630-62ec-54d4-af2b-f9b4c804b5f3', 10, 'The Scraping', 'In which an entire lane in the Unmarked disappears overnight. Ilse finds fresh ash-ink shavings on the Guild Tower''s steps the next morning.

Below the bridges the canal ran black and slow, carrying the day''s scraped lines out toward the sea.

For the first time, Ilse wondered whether the Guild had ever been drawing the city, or only drawing it smaller.

"If you''re going to change the city, change it so the bakery''s closer," Pell said.

The Guild bells rang the hour, and somewhere a street creaked as a surveyor''s correction took hold.

Ilse thought of Master Oren''s hands, steady even when the lamp guttered, and tried to make her own as still.

"Everyone says the Unmarked''s empty." Pell paused. "Funny how they lock the gates, then."

Ilse did not sleep that night. She sat with the map and listened to the city breathe.', 'published', now() - interval '53.836 days', now() - interval '53.836 days'),
  ('5bda78ee-9818-52c2-a040-e956797e7e36', '38bf5630-62ec-54d4-af2b-f9b4c804b5f3', 11, 'Mother Agathe''s Tea', 'In which Mother Agathe invites Ilse to tea and offers her Oren''s old position if she hands over ''anything he left unfinished''. Ilse lies and says there was nothing.

Ash fell over Cindermere the way snow falls elsewhere, soft and constant, settling in the gutters and on the brims of hats.

She had spent six years learning to draw what was there. Nobody had taught her what to do when the truth itself was missing.

Mother Agathe said, "The Guild does not hide things, child. It decides what is worth seeing."

The Unmarked was quiet at this hour, its rooftops a jagged line against a sky the colour of old coins.

For the first time, Ilse wondered whether the Guild had ever been drawing the city, or only drawing it smaller.

"If you''re going to change the city, change it so the bakery''s closer," Pell said quietly.

By morning, the Guild had posted a notice on every door, and her name was on it.', 'published', now() - interval '51.585 days', now() - interval '51.585 days'),
  ('ab19a9c9-161a-543c-a244-84fcd8d357ce', '38bf5630-62ec-54d4-af2b-f9b4c804b5f3', 12, 'The Second Hand', 'In which comparing inks, Corvin realises the scraping is not done by the Guild''s pens. Someone else is drawing over the Guild''s maps, using a black ink that eats lines.

