insert into public.stories (id, author_id, title, slug, synopsis, status, rating, created_at)
values ('05777f18-1094-593a-aa62-a5c8e1560e84', 'b66ace35-7d2d-5a87-abc0-e5aa8741b15e', 'Salt and Starlight', 'salt-and-starlight', 'Navigator Marisol Quint can read the stars like a ledger, which is exactly why Captain Dorian Vey kidnaps her from the Admiralty''s flagship. He needs her to find the Drowned Light, a lighthouse that guides ships to a sea that no chart admits exists. She needs to escape. Neither of them needs the way the other one laughs.', 'completed', 'teen', now() - interval '120.73 days')
