insert into public.stories (id, author_id, title, slug, synopsis, status, rating, created_at)
values ('a3c50a76-8cd6-561e-a2bc-56f43dace8ae', '53c8c6e4-5f89-5bcb-a629-282e97ba3e5f', 'Signal Drift', 'signal-drift', 'Relay Station Kestrel sits at the edge of human space, passing messages between colonies that will never meet. When communications officer Ama Boateng starts receiving transmissions timestamped three days in the future, she has to decide whether to warn the crew about the disaster the messages describe, or find out who, or what, is sending them.', 'ongoing', 'everyone', now() - interval '6.87 days')
