-- The Ninefold Path (40 chapters)
insert into public.stories (id, author_id, title, slug, synopsis, status, rating, created_at)
values ('e52b45b3-2a54-56cf-acb1-0637ace80fa8', 'b66999fb-77b7-51da-a95d-f64a0003e286', 'The Ninefold Path', 'the-ninefold-path', 'Wei Lan''s family was destroyed in a single night, and the sect that did it now sits atop the Ninefold Mountain, untouchable. Crippled meridians and all, she enters that same sect as a servant disciple, carrying a broken jade slip with a cultivation method no one has practised in a thousand years. Revenge will take patience. The Ninefold Path will take everything else.', 'ongoing', 'teen', now() - interval '98.71 days')
on conflict (id) do nothing;
insert into public.story_genres (story_id, genre_id) select 'e52b45b3-2a54-56cf-acb1-0637ace80fa8', id from public.genres where slug in ('xianxia', 'action') on conflict do nothing;
