insert into public.stories (id, author_id, title, slug, synopsis, status, rating, created_at)
values ('8543874c-59aa-5c49-a7a1-7ac4191db19f', '271f978e-4288-5bd3-a8dc-7035441b8054', 'Hollowmere', 'hollowmere', 'Every seven years, the village of Hollowmere drains its lake for a single night and walks out onto the mud with lanterns. Nobody will tell newcomer Tess Harlow why. She has inherited her aunt''s house on the shore, a house with every mirror turned to face the wall, and a calendar on the kitchen door with tomorrow circled in red.', 'completed', 'teen', now() - interval '130.72 days')
