-- Reborn as the Dungeon's Accountant (30 chapters)
insert into public.stories (id, author_id, title, slug, synopsis, status, rating, created_at)
values ('7cd412ed-2a47-53de-a984-e67d223c5649', '7871dcac-1355-5d44-ae1b-0dbae85390ce', 'Reborn as the Dungeon''s Accountant', 'reborn-as-the-dungeons-accountant', 'Overworked auditor Kenji Mori dies at his desk and wakes up as the newest employee of the Fourth Labyrinth, a struggling dungeon on the brink of bankruptcy. The slimes are underpaid, the dragon is depressed, and the Dungeon Core has not filed a report in three hundred years. Kenji has a spreadsheet, a quill and one month before the Adventurers'' Guild buys the dungeon and turns it into a theme park.', 'ongoing', 'everyone', now() - interval '66.69 days')
