insert into public.stories (id, author_id, title, slug, synopsis, status, rating, created_at)
values ('28fba78c-6ad1-5894-a2d1-78f8f994db83', 'db1a6229-ecff-506c-a86a-26dba1aef994', 'Level Zero Healer', 'level-zero-healer', 'When the System arrived, everyone on Earth received a class. Nadia Okoro received [Healer], level zero, with a single skill that heals other people by taking their wounds onto herself. No party will take her. So she goes into the dungeons alone, levelling the hard way, one borrowed injury at a time.', 'ongoing', 'teen', now() - interval '88.89 days')
