-- The Quiet Year (20 chapters)
insert into public.stories (id, author_id, title, slug, synopsis, status, rating, created_at)
values ('beb87e81-0de9-5bb9-afdf-d6a5634c0f32', 'ce2e4569-4ae5-58d7-ad3a-bdd2e5ea96d6', 'The Quiet Year', 'the-quiet-year', 'After burning out of a city job she was very good at, Hana Lindqvist takes over her late grandmother''s bookshop in a coastal town where nothing happens. She plans to sell it by spring. Then the regulars start arriving: a retired fisherman who reads poetry, a teenager hiding from home, a baker who leaves bread on the step. One year. Four seasons. No big plans at all.', 'completed', 'everyone', now() - interval '105.74 days')
on conflict (id) do nothing;
