insert into public.stories (id, author_id, title, slug, synopsis, status, rating, created_at)
values ('0d34a01c-205a-5dc5-aed1-7231e016c33a', '2f99bc0d-1ffc-574e-a9fe-0aa5ecbbeb1c', 'Red Line', 'red-line', 'Marco Vidal used to plan heists for a living, until one went wrong and his partner took the fall. Five years later she''s out of prison and asking for one favour: rob the private vault under the city''s new metro line before it opens. The vault belongs to the man who framed her. The metro opens in nine days. The crew is rusty, the plan is impossible, and someone on the inside is already talking.', 'completed', 'teen', now() - interval '140.73 days')
