insert into public.stories (id, author_id, title, slug, synopsis, status, rating, created_at)
values ('d7c9dac0-6e19-521b-ae48-f40d07b58268', '81da30f6-c2a1-5fdd-a854-7537bb7df7f3', 'The Last Lighthouse Keeper', 'the-last-lighthouse-keeper', 'In 1987 the keeper of Skerrow Light vanished during a storm, leaving the lamp burning and a meal half-eaten on the table. Thirty-five years later the lighthouse is being sold, and archivist Nell Carrick is sent to catalogue what remains. She finds the keeper''s logbook, and an entry dated the night after he disappeared.', 'completed', 'everyone', now() - interval '125.85 days')
