values ('0bb4c1d7-958d-5c7f-a984-2ec5bb31b5ca', 'b66ace35-7d2d-5a87-abc0-e5aa8741b15e', 'The Winter Envoy', 'the-winter-envoy', 'Every hundred years, a human is sent to the Winter Court as envoy and returns with a treaty that keeps the frost out of the mortal kingdoms. Nobody remembers that every envoy came back changed. Seamstress Rowan Ashby is chosen by mistake, and she has three months to negotiate with the coldest, cleverest prince in the court before the first snow becomes a forever winter.', 'ongoing', 'teen', now() - interval '60.68 days')
on conflict (id) do nothing;
insert into public.story_genres (story_id, genre_id) select '0bb4c1d7-958d-5c7f-a984-2ec5bb31b5ca', id from public.genres where slug in ('fantasy', 'romance') on conflict do nothing;
