insert into public.story_tags (story_id, tag_id) select '0bb4c1d7-958d-5c7f-a984-2ec5bb31b5ca', id from public.tags where slug in ('court-intrigue', 'fae', 'slow-burn') on conflict do nothing;
insert into public.chapters (id, story_id, number, title, body, status, published_at, created_at) values
  ('773d530e-a0eb-52c9-af6a-158c7a378cd9', '0bb4c1d7-958d-5c7f-a984-2ec5bb31b5ca', 1, 'The White Cloak', 'The envoy was supposed to be the Duke''s daughter. Everyone knew it. The Duke''s daughter had been fitted for the envoy''s white cloak for a year, and Rowan Ashby had sewn every stitch of it.

Which was why, when the Winter Court''s herald stepped through the frost-door in the great hall and pointed a gloved finger at the person wearing the cloak, Rowan was the only one in the room who did not look surprised. She had put it on for a final fitting. The Duke''s daughter was late.

''The envoy is chosen,'' said the herald, and the doors of the hall blew shut on their own.

Snow drifted through the halls of the Winter Court without ever touching the floor, hanging in the air like held breath.

Prince Caelan said, "In this court, mortal, a promise is a blade. Hold yours by the handle."

That night, frost crept across her window in the shape of a word she did not know.', 'published', now() - interval '59.685 days', now() - interval '59.685 days'),
  ('a88cb753-148a-5249-a04c-1f59e175cb1f', '0bb4c1d7-958d-5c7f-a984-2ec5bb31b5ca', 2, 'The Court of Ice', 'In which Rowan arrives at the Winter Court, where she must negotiate the century''s treaty before the first snow, or winter will never leave the mortal lands.

In Rowan''s chambers the fire burned cold and pale, giving light but no warmth at all.

If the treaty failed, her village would freeze. Rowan kept that thought in her pocket like a needle.

Prince Caelan said, "In this court, mortal, a promise is a blade. Hold yours by the handle."

The ice walls glowed blue from within, and somewhere far below them, something vast and slow was turning in its sleep.

She was beginning to learn the court''s language: what was said, what was meant, and the long cold silence in between.

"Every envoy thinks they are the clever one." Lady Isolde paused. "None of them were."

That night, frost crept across her window in the shape of a word she did not know.', 'published', now() - interval '58.190 days', now() - interval '58.190 days'),
  ('0a2a9c5a-1bd4-5aeb-ad65-038132ce9af4', '0bb4c1d7-958d-5c7f-a984-2ec5bb31b5ca', 3, 'Fennick', 'In which a small fox-eared servant named Fennick is assigned to her and teaches her the first rule of the court: never say thank you.

Snow drifted through the halls of the Winter Court without ever touching the floor, hanging in the air like held breath.

Every day in the Winter Court took a little warmth from her. She had started counting what was left.

Prince Caelan said, "You sew as though you could stitch the world back together. It is an admirable delusion."

Outside the palace, the frozen forest stretched to the horizon, every branch sheathed in glass.

If the treaty failed, her village would freeze. Rowan kept that thought in her pocket like a needle.

Prince Caelan said, "In this court, mortal, a promise is a blade. Hold yours by the handle."

In the morning, the treaty draft on her desk had been rewritten in a hand that was not hers.', 'published', now() - interval '56.277 days', now() - interval '56.277 days'),
  ('e0c21b9a-0080-5daf-a8e4-d0d5f78e20be', '0bb4c1d7-958d-5c7f-a984-2ec5bb31b5ca', 4, 'Prince Caelan', 'In which Rowan meets Prince Caelan, the court''s chief negotiator, who is cold, precise and openly amused by her lack of training.

In Rowan''s chambers the fire burned cold and pale, giving light but no warmth at all.

Rowan had spent her life measuring other people for clothes they would wear to places she would never go.

"Never thank anyone here. It''s like handing them a key to your house," Fennick said.

The ice walls glowed blue from within, and somewhere far below them, something vast and slow was turning in its sleep.

Every day in the Winter Court took a little warmth from her. She had started counting what was left.

In the morning, the treaty draft on her desk had been rewritten in a hand that was not hers.', 'published', now() - interval '54.601 days', now() - interval '54.601 days'),
  ('93b506cd-7531-536f-a29b-8b3215831014', '0bb4c1d7-958d-5c7f-a984-2ec5bb31b5ca', 5, 'The First Session', 'In which The first negotiation goes badly. Caelan traps her into agreeing that mortal envoys ''give what is asked'', and Rowan realises the treaty is a trap too.

Snow drifted through the halls of the Winter Court without ever touching the floor, hanging in the air like held breath.

Caelan infuriated her. She was alarmed to notice she was looking forward to being infuriated.

Fennick said, "The Prince is watching you again. That''s either flattering or fatal. Usually both."

Outside the palace, the frozen forest stretched to the horizon, every branch sheathed in glass.

Rowan had spent her life measuring other people for clothes they would wear to places she would never go.

"Never thank anyone here. It''s like handing them a key to your house," Fennick said.

That night, frost crept across her window in the shape of a word she did not know.', 'published', now() - interval '53.110 days', now() - interval '53.110 days'),
