-- Orbital Garden (22 chapters)
insert into public.stories (id, author_id, title, slug, synopsis, status, rating, created_at)
values ('93b29c91-ec51-57f0-a4b9-46560e64fb7e', '53c8c6e4-5f89-5bcb-a629-282e97ba3e5f', 'Orbital Garden', 'orbital-garden', 'Agronomist Femi Adeyemi signs up for a quiet posting tending the hydroponic gardens of Meridian, a sleepy research station in orbit around Mars. The station has nine residents, one very opinionated AI, and a garden that grows strawberries, rice and, recently, a plant nobody planted. No villains. No explosions. Just tomatoes, neighbours and the slow business of making a place a home.', 'ongoing', 'everyone', now() - interval '5.78 days')
