insert into public.stories (id, author_id, title, slug, synopsis, status, rating, created_at)
values ('12ccfce4-55c7-5715-a619-c32aae79e154', '2f99bc0d-1ffc-574e-a9fe-0aa5ecbbeb1c', 'Blade of the Ninth Moon', 'blade-of-the-ninth-moon', 'Once every nine years, under the ninth full moon, the Free Cities hold a tournament whose champion may ask any one thing of the Council. Kira Thane, a dockworker who learned the sword from a drunk old soldier, wants only one thing: her brother released from the mines. To win, she will face the finest blades of nine cities, and the champion who disgraced her teacher.', 'ongoing', 'teen', now() - interval '80.85 days')
