insert into public.stories (id, author_id, title, slug, synopsis, status, rating, created_at)
values ('fe5a7c01-daca-566f-a1ab-0017b479c792', '7871dcac-1355-5d44-ae1b-0dbae85390ce', 'The Paper Witch', 'the-paper-witch', 'In a mountain town where the river spirits must be asked permission for every bridge, Aiko folds paper birds that fly. She keeps it secret, because the last girl who could do that was taken by the Shrine. When a flood washes away the town''s bridges and the spirits refuse to speak, Aiko''s paper is the only thing that can reach them.', 'ongoing', 'everyone', now() - interval '50.95 days')
